"""
Servidor principal FastAPI para la aplicación de Teléfono Descompuesto y Enriquecedor de Párrafos.
Ofrece endpoints REST y sirve la interfaz web frontend.
"""
from typing import List, Optional
import os
from fastapi import FastAPI, HTTPException
from fastapi.staticfiles import StaticFiles
from fastapi.responses import FileResponse
from pydantic import BaseModel, Field

from enricher import enrich_text_heuristic
from whispers import run_whispers_chain, CHAOS_PRESETS, SUPPORTED_LANGUAGES
from llm_client import LLMClient, DEFAULT_SYSTEM_ENRICHER, DEFAULT_SYSTEM_WHISPERS

app = FastAPI(
    title="Traductor Teléfono Descompuesto & Enriquecedor Barroco",
    description="Aplicación web interactiva híbrida (heurística/APIs de traducción y LLM opcional).",
    version="1.0.0"
)

# Servir archivos estáticos
STATIC_DIR = os.path.join(os.path.dirname(__file__), "static")
app.mount("/static", StaticFiles(directory=STATIC_DIR), name="static")

# Modelos Pydantic para validación de entrada
class EnrichRequest(BaseModel):
    text: str = Field(..., min_length=1, description="Texto de entrada a enriquecer")
    mode: str = Field("heuristic", description="'heuristic' o 'llm'")
    formality_level: int = Field(2, ge=1, le=3, description="Nivel de formalidad (1 a 3)")
    llm_base_url: Optional[str] = Field("https://api.groq.com/openai/v1")
    llm_api_key: Optional[str] = Field(None)
    llm_model: Optional[str] = Field("llama-3.1-8b-instant")

class WhispersRequest(BaseModel):
    text: str = Field(..., min_length=1, description="Texto original a distorsionar")
    mode: str = Field("chain", description="'chain' (traducción real encadenada) o 'llm'")
    preset: Optional[str] = Field("clasico", description="Nombre del preset: ligero, clasico, exotico, maximo_caos")
    custom_chain: Optional[List[str]] = Field(None, description="Cadena personalizada de códigos de idioma")
    llm_base_url: Optional[str] = Field("https://api.groq.com/openai/v1")
    llm_api_key: Optional[str] = Field(None)
    llm_model: Optional[str] = Field("llama-3.1-8b-instant")

@app.get("/")
def serve_index():
    """Entrega la página web principal."""
    index_path = os.path.join(STATIC_DIR, "index.html")
    if not os.path.exists(index_path):
        raise HTTPException(status_code=404, detail="Frontend index.html no encontrado")
    return FileResponse(index_path)

@app.get("/api/languages")
def get_languages():
    """Retorna los idiomas soportados y los presets de cadenas de teléfono descompuesto."""
    return {
        "languages": SUPPORTED_LANGUAGES,
        "presets": CHAOS_PRESETS
    }

@app.post("/api/enrich")
def enrich_text_endpoint(req: EnrichRequest):
    """
    Enriquece un párrafo coloquial/urbano a lenguaje barroco o académico rimbombante.
    """
    if req.mode == "llm":
        client = LLMClient(
            base_url=req.llm_base_url or "https://api.groq.com/openai/v1",
            api_key=req.llm_api_key,
            model=req.llm_model or "llama-3.1-8b-instant"
        )
        if not client.is_configured():
            raise HTTPException(
                status_code=400,
                detail="El modo LLM requiere una API Key válida (ej. de Groq u OpenRouter) o un host local como Ollama."
            )
        try:
            result = client.generate(req.text, DEFAULT_SYSTEM_ENRICHER)
            return {"original": req.text, "result": result, "mode": "llm"}
        except RuntimeError as exc:
            raise HTTPException(status_code=502, detail=str(exc))

    # Modo heurístico de alta velocidad (sin costo de API)
    result = enrich_text_heuristic(req.text, req.formality_level)
    return {"original": req.text, "result": result, "mode": "heuristic"}

@app.post("/api/whispers")
def whispers_endpoint(req: WhispersRequest):
    """
    Simula el 'teléfono descompuesto' mediante saltos idiomáticos o simulación con LLM.
    """
    if req.mode == "llm":
        client = LLMClient(
            base_url=req.llm_base_url or "https://api.groq.com/openai/v1",
            api_key=req.llm_api_key,
            model=req.llm_model or "llama-3.1-8b-instant"
        )
        if not client.is_configured():
            raise HTTPException(
                status_code=400,
                detail="El modo LLM requiere una API Key válida o servicio local (Ollama)."
            )
        try:
            result = client.generate(req.text, DEFAULT_SYSTEM_WHISPERS)
            return {
                "original": req.text,
                "final": result,
                "chain": ["es", "llm-chaos", "es"],
                "steps": [
                    {"step": 0, "lang_name": "Español Original", "text": req.text},
                    {"step": 1, "lang_name": "Traducción Cruda Descompuesta", "text": result}
                ],
                "mode": "llm"
            }
        except RuntimeError as exc:
            raise HTTPException(status_code=502, detail=str(exc))

    # Modo cadena de traducción real
    chain = req.custom_chain
    if not chain:
        chain = CHAOS_PRESETS.get(req.preset or "clasico", CHAOS_PRESETS["clasico"])

    res = run_whispers_chain(req.text, chain=chain)
    res["mode"] = "chain"
    return res

/* Estilos y Sistema de Tokens de Diseño para Retórica & Descalabro */
:root {
  --font-serif: 'Cinzel', serif;
  --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  --font-mono: 'JetBrains Mono', monospace;

  /* Tokens de Color Semántico */
  --bg-app: #0e1117;
  --bg-surface: #161b22;
  --bg-surface-raised: #21262d;
  --bg-input: #0d1117;
  --border-subtle: #30363d;
  --border-focus: #58a6ff;

  --text-main: #f0f6fc;
  --text-muted: #8b949e;
  --text-accent: #e3b341;
  --text-gold: #f1c40f;

  --primary: #8957e5;
  --primary-hover: #9e6ff5;
  --primary-glow: rgba(137, 87, 229, 0.35);

  --accent-cyan: #39c5cf;
  --danger: #f85149;
  --success: #3fb950;

  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;

  --transition-fast: 0.15s cubic-bezier(0.16, 1, 0.3, 1);
  --transition-normal: 0.25s cubic-bezier(0.16, 1, 0.3, 1);
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-sans);
  background-color: var(--bg-app);
  color: var(--text-main);
  line-height: 1.6;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  border: 0;
}

/* Cabecera */
.app-header {
  background: var(--bg-surface);
  border-bottom: 1px solid var(--border-subtle);
  padding: 1.25rem 2rem;
  position: sticky;
  top: 0;
  z-index: 100;
}

.header-container {
  max-width: 1200px;
  margin: 0 auto;
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  align-items: center;
  gap: 1.5rem;
}

.logo-group {
  display: flex;
  align-items: center;
  gap: 0.85rem;
}

.logo-icon {
  font-size: 2.2rem;
}

.logo-title {
  font-family: var(--font-serif);
  font-size: clamp(1.2rem, 1rem + 0.8vw, 1.6rem);
  font-weight: 700;
  color: var(--text-gold);
  letter-spacing: 0.5px;
}

.logo-subtitle {
  font-size: 0.85rem;
  color: var(--text-muted);
}

/* Pestañas de Navegación */
.nav-tabs {
  display: flex;
  gap: 0.5rem;
  background: var(--bg-app);
  padding: 4px;
  border-radius: var(--radius-md);
  border: 1px solid var(--border-subtle);
}

.tab-btn {
  background: transparent;
  color: var(--text-muted);
  border: none;
  padding: 0.6rem 1.1rem;
  font-size: 0.9rem;
  font-weight: 600;
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: all var(--transition-fast);
}

.tab-btn:hover {
  color: var(--text-main);
  background: var(--bg-surface-raised);
}

.tab-btn:focus-visible {
  outline: 2px solid var(--border-focus);
  outline-offset: 2px;
}

.tab-btn.active {
  background: var(--primary);
  color: #fff;
  box-shadow: 0 2px 10px var(--primary-glow);
}

/* Contenido Principal */
.main-content {
  max-width: 1200px;
  width: 100%;
  margin: 2rem auto;
  padding: 0 1.5rem;
  flex: 1;
}

/* Drawer LLM Opcional */
.llm-drawer {
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  margin-bottom: 2rem;
  overflow: hidden;
  transition: border-color var(--transition-fast);
}

.llm-drawer:hover {
  border-color: #484f58;
}

.llm-drawer-summary {
  padding: 1rem 1.25rem;
  cursor: pointer;
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--text-accent);
  display: flex;
  justify-content: space-between;
  align-items: center;
  user-select: none;
}

.llm-drawer-summary:focus-visible {
  outline: 2px solid var(--border-focus);
}

.drawer-badge {
  font-size: 0.75rem;
  padding: 2px 8px;
  border-radius: 12px;
  background: rgba(227, 179, 65, 0.15);
  border: 1px solid rgba(227, 179, 65, 0.3);
  color: var(--text-accent);
}

.llm-drawer-body {
  padding: 1.25rem;
  border-top: 1px solid var(--border-subtle);
  background: var(--bg-input);
}

.drawer-tip {
  font-size: 0.85rem;
  color: var(--text-muted);
  margin-bottom: 1rem;
}

.form-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  gap: 1rem;
}

.form-group {
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
}

.form-group label {
  font-size: 0.8rem;
  font-weight: 500;
  color: var(--text-muted);
}

input[type="text"],
input[type="password"],
select,
textarea {
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  color: var(--text-main);
  border-radius: var(--radius-sm);
  padding: 0.65rem 0.85rem;
  font-family: inherit;
  font-size: 0.95rem;
  transition: border-color var(--transition-fast), box-shadow var(--transition-fast);
}

input:focus-visible,
select:focus-visible,
textarea:focus-visible {
  outline: none;
  border-color: var(--border-focus);
  box-shadow: 0 0 0 3px rgba(88, 166, 255, 0.2);
}

/* Paneles */
.tab-panel {
  display: none;
  flex-direction: column;
  gap: 1.5rem;
}

.tab-panel.active {
  display: flex;
}

.panel-hero {
  margin-bottom: 0.5rem;
}

.panel-hero h2 {
  font-family: var(--font-serif);
  font-size: 1.4rem;
  color: var(--text-main);
  margin-bottom: 0.25rem;
}

.panel-hero p {
  color: var(--text-muted);
  font-size: 0.95rem;
}

/* Rejilla de Trabajo */
.workbench-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 1.5rem;
}

@media (min-width: 900px) {
  .workbench-grid {
    grid-template-columns: 1fr 1fr;
  }
}

.card {
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  padding: 1.5rem;
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.card-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 0.5rem;
}

.card-header h3 {
  font-size: 1.05rem;
  font-weight: 600;
  color: var(--text-accent);
}

.preset-pills {
  display: flex;
  gap: 0.4rem;
}

.pill-btn {
  background: var(--bg-surface-raised);
  border: 1px solid var(--border-subtle);
  color: var(--text-muted);
  font-size: 0.75rem;
  padding: 3px 9px;
  border-radius: 12px;
  cursor: pointer;
  transition: all var(--transition-fast);
}

.pill-btn:hover {
  color: var(--text-main);
  background: #2d333b;
  border-color: #484f58;
}

.pill-btn:focus-visible {
  outline: 2px solid var(--border-focus);
}

textarea {
  width: 100%;
  resize: vertical;
  min-height: 160px;
  line-height: 1.5;
}

.controls-row {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  gap: 1rem;
}

.mode-select-group,
.level-select-group {
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
  flex: 1;
  min-width: 150px;
}

.mode-select-group label,
.level-select-group label {
  font-size: 0.8rem;
  font-weight: 500;
  color: var(--text-muted);
}

.btn-primary {
  background: var(--primary);
  color: #fff;
  border: none;
  font-weight: 600;
  padding: 0.75rem 1.4rem;
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: background var(--transition-fast), transform var(--transition-fast), box-shadow var(--transition-fast);
  white-space: nowrap;
}

.btn-primary:hover {
  background: var(--primary-hover);
  box-shadow: 0 4px 14px var(--primary-glow);
  transform: translateY(-1px);
}

.btn-primary:active {
  transform: translateY(1px);
}

.btn-primary:focus-visible {
  outline: 2px solid var(--border-focus);
  outline-offset: 2px;
}

.btn-primary:disabled {
  opacity: 0.6;
  cursor: not-allowed;
  transform: none;
}

/* Caja de Salida */
.output-box {
  background: var(--bg-input);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  padding: 1.25rem;
  min-height: 220px;
  font-size: 1.05rem;
  line-height: 1.7;
  color: var(--text-main);
  overflow-y: auto;
  position: relative;
  white-space: pre-wrap;
}

.output-box.baroque-style {
  font-family: 'Georgia', serif;
  font-style: italic;
  color: #f7e7c4;
  border-left: 4px solid var(--text-gold);
}

.placeholder-text {
  color: var(--text-muted);
  font-style: italic;
}

.copy-btn {
  background: transparent;
  border: 1px solid var(--border-subtle);
  color: var(--text-muted);
  font-size: 0.8rem;
  padding: 4px 10px;
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: all var(--transition-fast);
}

.copy-btn:hover {
  color: var(--text-main);
  background: var(--bg-surface-raised);
}

.copy-btn:focus-visible {
  outline: 2px solid var(--border-focus);
}

/* Timeline de Pasos */
.steps-section {
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  padding: 1.5rem;
  margin-top: 1.5rem;
}

.steps-section h3 {
  font-size: 1.1rem;
  margin-bottom: 1rem;
  color: var(--accent-cyan);
}

.timeline-container {
  display: flex;
  flex-direction: column;
  gap: 0.85rem;
}

.timeline-step {
  background: var(--bg-input);
  border: 1px solid var(--border-subtle);
  border-left: 3px solid var(--primary);
  border-radius: var(--radius-sm);
  padding: 0.85rem 1rem;
}

.timeline-step-header {
  display: flex;
  justify-content: space-between;
  margin-bottom: 0.35rem;
  font-size: 0.8rem;
  color: var(--text-accent);
  font-weight: 600;
}

.timeline-step-text {
  font-size: 0.95rem;
  color: var(--text-main);
}

/* Spinner / Estado de Carga */
.loading-indicator {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  color: var(--text-accent);
  font-size: 0.9rem;
}

.spinner {
  width: 18px;
  height: 18px;
  border: 2px solid rgba(227, 179, 65, 0.2);
  border-top-color: var(--text-accent);
  border-radius: 50%;
  animation: spin 0.8s linear infinite;
}

@keyframes spin {
  to { transform: rotate(360deg); }
}

/* Footer */
.app-footer {
  text-align: center;
  padding: 1.5rem;
  font-size: 0.8rem;
  color: var(--text-muted);
  border-top: 1px solid var(--border-subtle);
  margin-top: auto;
}

// Lógica de interacción frontend para Retórica & Descalabro

// Muestras predeterminadas para enriquecedor
const ENRICHER_SAMPLES = {
  1: "Sigue tu camino que sin ti me va mejor, ahora tengo otras que me lo hacen mejor",
  2: "Hola amigo, hoy no tengo plata para salir a comer, pero la noche está linda para ir a la playa",
  3: "Me rompiste el corazón y me engañaste, no te creo nada de lo que dices, callate ya"
};

// Muestras predeterminadas para teléfono descompuesto
const WHISPERS_SAMPLES = {
  1: `Rudeboyz
Ajá
Yo, esto es una historia real, mi amor
Tú sabes que te estoy hablando a ti
Me has vuelto un mare, mamacita
Dice
Hoy pienso que ella me ama
Porque amanezco en su cama
Van varias noche de eso
Creo que la matan mis besos
Siento que puedo nadar
Flotando entre sus piernas pongo dulce el mar
Siento que en sus aguas puedo navegar
Ya llegue a la orilla y no me voy a ahogar
Yo no necesito un GPS
Pa' llegarte siempre donde estés
Déjame contarte, yo no vine a amarte
Sólo vine a darte hasta las seis`,
  2: "No me vuelvas a llamar porque ya no me importa nada de lo que hagas con tu vida"
};

// Navegación entre pestañas
document.addEventListener("DOMContentLoaded", () => {
  const tabEnricher = document.getElementById("tab-enricher");
  const tabWhispers = document.getElementById("tab-whispers");
  const panelEnricher = document.getElementById("panel-enricher");
  const panelWhispers = document.getElementById("panel-whispers");

  tabEnricher.addEventListener("click", () => {
    tabEnricher.classList.add("active");
    tabEnricher.setAttribute("aria-selected", "true");
    tabWhispers.classList.remove("active");
    tabWhispers.setAttribute("aria-selected", "false");

    panelEnricher.classList.add("active");
    panelEnricher.removeAttribute("hidden");
    panelWhispers.classList.remove("active");
    panelWhispers.setAttribute("hidden", "true");
  });

  tabWhispers.addEventListener("click", () => {
    tabWhispers.classList.add("active");
    tabWhispers.setAttribute("aria-selected", "true");
    tabEnricher.classList.remove("active");
    tabEnricher.setAttribute("aria-selected", "false");

    panelWhispers.classList.add("active");
    panelWhispers.removeAttribute("hidden");
    panelEnricher.classList.remove("active");
    panelEnricher.setAttribute("hidden", "true");
  });

  // Cargar muestra 1 por defecto en el enriquecedor
  loadEnricherSample(1);
});

function loadEnricherSample(id) {
  const input = document.getElementById("enricher-input");
  if (ENRICHER_SAMPLES[id]) {
    input.value = ENRICHER_SAMPLES[id];
  }
}

function loadWhispersSample(id) {
  const input = document.getElementById("whispers-input");
  if (WHISPERS_SAMPLES[id]) {
    input.value = WHISPERS_SAMPLES[id];
  }
}

function getLLMConfig() {
  return {
    llm_base_url: document.getElementById("llm-base-url").value.trim(),
    llm_api_key: document.getElementById("llm-api-key").value.trim() || null,
    llm_model: document.getElementById("llm-model").value.trim()
  };
}

// Handler de Enriquecimiento
async function handleEnrich() {
  const text = document.getElementById("enricher-input").value.trim();
  const engine = document.getElementById("enricher-engine").value;
  const level = parseInt(document.getElementById("enricher-level").value, 10);
  const outputContainer = document.getElementById("enricher-output-container");
  const btn = document.getElementById("btn-run-enricher");

  if (!text) {
    alert("Por favor introduce una frase o texto para enriquecer.");
    return;
  }

  btn.disabled = true;
  outputContainer.className = "output-box";
  outputContainer.innerHTML = `
    <div class="loading-indicator">
      <div class="spinner"></div>
      <span>Destilando elocuencia y rebuscamiento barroco...</span>
    </div>
  `;

  try {
    const payload = {
      text,
      mode: engine,
      formality_level: level,
      ...getLLMConfig()
    };

    const res = await fetch("/api/enrich", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload)
    });

    const data = await res.json();
    if (!res.ok) {
      throw new Error(data.detail || "Error en el servidor al enriquecer el texto.");
    }

    outputContainer.className = "output-box baroque-style";
    outputContainer.innerHTML = `<span id="enricher-output">${escapeHtml(data.result)}</span>`;
  } catch (err) {
    outputContainer.className = "output-box";
    outputContainer.innerHTML = `<p style="color: var(--danger);">⚠️ ${escapeHtml(err.message)}</p>`;
  } finally {
    btn.disabled = false;
  }
}

// Handler de Teléfono Descompuesto
async function handleWhispers() {
  const text = document.getElementById("whispers-input").value.trim();
  const engine = document.getElementById("whispers-engine").value;
  const preset = document.getElementById("whispers-preset").value;
  const outputContainer = document.getElementById("whispers-output-container");
  const stepsSection = document.getElementById("whispers-steps-section");
  const stepsTimeline = document.getElementById("steps-timeline");
  const btn = document.getElementById("btn-run-whispers");

  if (!text) {
    alert("Por favor introduce un texto para someter al teléfono descompuesto.");
    return;
  }

  btn.disabled = true;
  outputContainer.innerHTML = `
    <div class="loading-indicator">
      <div class="spinner"></div>
      <span>Haciendo saltos de idioma por el mundo...</span>
    </div>
  `;
  stepsSection.style.display = "none";
  stepsTimeline.innerHTML = "";

  try {
    const payload = {
      text,
      mode: engine,
      preset: preset,
      ...getLLMConfig()
    };

    const res = await fetch("/api/whispers", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload)
    });

    const data = await res.json();
    if (!res.ok) {
      throw new Error(data.detail || "Error al procesar teléfono descompuesto.");
    }

    outputContainer.innerHTML = `<div id="whispers-final-text"><strong>${escapeHtml(data.final)}</strong></div>`;

