          </div>
          <div class="timeline-step-text">${escapeHtml(step.text)}</div>
        </div>
      `).join("");
      stepsSection.style.display = "block";
    }
  } catch (err) {
    outputContainer.innerHTML = `<p style="color: var(--danger);">⚠️ ${escapeHtml(err.message)}</p>`;
  } finally {
    btn.disabled = false;
  }
}

